(() => {
  'use strict';
  const data = structuredClone(window.NumaData);
  const app = document.querySelector('#app');
  const dialog = document.querySelector('#detail-dialog');
  const state = {theme:new URLSearchParams(location.search).get('theme')==='dark'?'dark':'light',dealSearch:'',dealFilter:'Todos',dealView:'board',transactionFilter:'Todas',personSearch:'',department:'Todos',feedFilter:'Para você',comments:null,eventJoined:false,quizStep:0,quizAnswers:[],quizDone:false,course:0,period:'30',channel:'Todos os canais',calc:{type:'Website',pages:8,complexity:'Completo',deadline:'Flexível',rate:120,content:false,prototype:true,support:false},scenarios:[],aiPrompt:'Crie uma proposta para o projeto de identidade da Casa Lina. Quero uma apresentação simples, com etapas, entregas e investimento.',aiKind:'proposal',aiEditing:false,aiDraftHTML:null,chatInput:''};
  let galleryObserver, toastTimer, dialogOpener;
  const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',briefcase:'M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2 M3 7h18v13H3z M3 12a24 24 0 0 0 18 0 M10 12v3h4v-3',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0a4 4 0 0 1 8 0',chart:'M4 3v17h17 M8 15l4-5 4 2 5-7',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',message:'M21 11.5a8.5 8.5 0 0 1-8.5 8.5a9 9 0 0 1-4-.9L3 21l1.9-5.5a9 9 0 0 1-.9-4A8.5 8.5 0 0 1 12.5 3H13a8.5 8.5 0 0 1 8 8v.5z',book:'M3 3h6a4 4 0 0 1 3 1.5A4 4 0 0 1 15 3h6v17h-6a4 4 0 0 0-3 1.5A4 4 0 0 0 9 20H3z M12 5v16',shapes:'M12 3l5 8H7z M3 15h7v7H3z M21 18.5a3.5 3.5 0 1 1-7 0a3.5 3.5 0 0 1 7 0',calculator:'M5 2h14v20H5z M8 6h8 M8 11h1 M15 11h1 M8 15h1 M15 15h1 M8 19h1 M15 19h1',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0a8 8 0 0 1 16 0',arrow:'M4 12h16 M14 6l6 6-6 6',back:'M20 12H4 M10 6l-6 6 6 6',chevron:'M9 5l7 7-7 7',down:'M6 9l6 6 6-6',plus:'M12 5v14 M5 12h14',close:'M6 6l12 12 M6 18L18 6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',sun:'M12 8a4 4 0 1 1 0 8a4 4 0 0 1 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1',moon:'M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10',more:'M4 12h.01 M12 12h.01 M20 12h.01',check:'M5 12l4 4L19 6',clock:'M12 8v4l3 2 M21 12a9 9 0 1 1-18 0a9 9 0 0 1 18 0',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16',mail:'M3 5h18v14H3z M3 5l9 7 9-7',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',bookmark:'M6 3h12v18l-6-4-6 4z',file:'M14 2H5v20h14V7z M14 2v6h5 M8 13h8 M8 17h6',copy:'M9 8h12v13H9z M5 16H3V3h12v2',play:'M8 4l13 8-13 8z',pin:'M16 3l5 5-4 3-1 5-2 2-3-3-7 7 M3 8l5-5 3 4 5 1 2 2-7 7-2-2-1-5z',wallet:'M3 6h18v15H3z M3 6V3h15v3 M17 12h4v4h-4z',trend:'M3 17l6-6 4 4 8-10 M15 5h6v6',target:'M21 12a9 9 0 1 1-18 0a9 9 0 0 1 18 0 M17 12a5 5 0 1 1-10 0a5 5 0 0 1 10 0 M12 10v4 M10 12h4',list:'M9 6h12 M9 12h12 M9 18h12 M3 6h.01 M3 12h.01 M3 18h.01',filter:'M4 7h16 M7 12h10 M10 17h4',location:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0 M15 10a3 3 0 1 1-6 0a3 3 0 0 1 6 0',award:'M16 16l2 6-6-3-6 3 2-6 M19 9a7 7 0 1 1-14 0a7 7 0 0 1 14 0',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',edit:'M16 3l5 5-12 12-6 1 1-6z M13 6l5 5',send:'M22 2l-7 20-4-9-9-4z M22 2L11 13'};
  const icon=(name,size=17)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=value=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(value);
  const number=value=>new Intl.NumberFormat('pt-BR').format(value);
  const percent=value=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:1}).format(value)+'%';
  const sum=(rows,key)=>rows.reduce((total,item)=>total+item[key],0);
  const initials=name=>name.split(' ').map(n=>n[0]).slice(0,2).join('');
  const avatar=(id=0,name='Marina Almeida',size='')=>`<span class="avatar ${size} ${id<5?'photo':''}" ${id<5?`style="background-position-x:${id*25}%"`:''} aria-hidden="true">${id<5?'':esc(initials(name))}</span>`;
  const mark=(letter,color='purple')=>`<span class="company-mark ${color}" aria-hidden="true">${esc(letter)}</span>`;
  const brand=()=>`<span class="brand-icon"><svg viewBox="0 0 28 28" fill="none" aria-hidden="true"><path d="M5 23V5h5l8 18h5V5h-5v18L10 5H5" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/></svg></span>`;
  const button=(text,action,leading='',extra='')=>`<button class="button ${extra}" data-action="${action}">${leading?icon(leading,14):''}${text}</button>`;
  const smallButton=(name,action,label,attrs='')=>`<button class="icon-button" data-action="${action}" aria-label="${label}" title="${label}" ${attrs}>${icon(name,16)}</button>`;
  const chip=(text,color='')=>`<span class="chip ${color}">${text}</span>`;
  const progress=(value)=>`<div class="tiny-progress"><span style="width:${Math.max(0,Math.min(100,value))}%"></span></div>`;
  const stat=(label,value,change,foot='vs. mês anterior',symbol='trend')=>`<div class="stat"><div class="stat-label">${label}${icon(symbol,14)}</div><div class="stat-value">${value}</div><div class="stat-foot"><span class="positive">${change}</span><span>${foot}</span></div></div>`;
  const tabs=(items,value,action)=>`<div class="tabs">${items.map(item=>`<button class="tab ${item===value?'active':''}" data-action="${action}" data-value="${esc(item)}" aria-pressed="${item===value}">${esc(item)}</button>`).join('')}</div>`;
  const heading=(title,description,actions='')=>`<div class="page-heading"><div><h1 tabindex="-1">${title}</h1><p>${description}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;
  const search=(name,value,placeholder)=>`<label class="search-field">${icon('search',14)}<input type="search" name="${name}" value="${esc(value)}" placeholder="${placeholder}" aria-label="${placeholder}"></label>`;
  const courseCover=id=>`course-cover cover-${id}`;
  const periodSelect=()=>`<select name="period" class="period-select" aria-label="Período">${[['7','Últimos 7 dias'],['30','Últimos 30 dias'],['90','Últimos 90 dias']].map(([v,t])=>`<option value="${v}" ${state.period===v?'selected':''}>${t}</option>`).join('')}</select>`;
  const chart=(values,second=null,label='Evolução no período',color='var(--accent)')=>{
    const max=Math.ceil(Math.max(...values,...(second||[]))/20)*20||100;
    const coords=series=>series.map((v,i)=>`${40+i*610/(series.length-1)},${178-v/max*136}`).join(' ');
    return `<div class="line-chart"><svg viewBox="0 0 700 225" role="img" aria-label="${esc(label)}"><title>${esc(label)}</title>${[0,.5,1].map(r=>`<line x1="40" y1="${178-r*136}" x2="660" y2="${178-r*136}"/><text x="3" y="${181-r*136}">${Math.round(max*r)}k</text>`).join('')}<polygon points="40,178 ${coords(values)} 650,178" fill="var(--accent-soft)" opacity=".8"/><polyline points="${coords(values)}" fill="none" stroke="${color}" stroke-width="2.5" stroke-linejoin="round"/>${second?`<polyline points="${coords(second)}" fill="none" stroke="#b8a2d7" stroke-dasharray="5 5" stroke-width="1.7"/>`:''}${values.map((v,i)=>`<circle cx="${40+i*610/(values.length-1)}" cy="${178-v/max*136}" r="3" fill="${color}" stroke="var(--surface)" stroke-width="1.5"><title>${number(Math.round(v*1000))} reais</title></circle>`).join('')}${['01 out','06 out','11 out','16 out','21 out','26 out'].map((t,i)=>`<text x="${40+i*122}" y="211" text-anchor="middle">${t}</text>`).join('')}</svg></div>`;
  };
  const reviewBar=(screen=null)=>`<header class="review-bar"><button class="review-home" data-action="gallery">${icon('grid',15)}<span>Explorar aplicativos</span></button><div class="review-center">${screen?`${smallButton('back','previous','Tela anterior')}<select name="screen-switch" aria-label="Escolher aplicativo">${data.screens.map(s=>`<option value="${s.id}" ${s.id===screen.id?'selected':''}>${s.name}</option>`).join('')}</select>${smallButton('arrow','next','Próxima tela')}<span>${data.screens.indexOf(screen)+1} de 9</span>`:'<span>Estudo visual · 9 aplicativos</span>'}</div><button class="theme-button" data-action="theme" aria-label="${state.theme==='light'?'Ativar modo escuro':'Ativar modo claro'}">${icon(state.theme==='light'?'moon':'sun',16)}<span>${state.theme==='light'?'Modo escuro':'Modo claro'}</span></button></header>`;
  function sidebar(screen){
    return `<aside class="app-sidebar"><div class="wordmark">${brand()}numa</div><div class="workspace"><span class="workspace-mark">a.</span><div><strong>Estúdio Aurora</strong><small>Espaço da equipe</small></div>${icon('down',12)}</div><div class="nav-label">${screen.section}</div><nav class="app-nav" aria-label="Navegação ilustrativa de ${screen.section}">${screen.nav.map((item,i)=>`<span class="nav-item ${i===0?'active':''}" ${i===0?'aria-current="page"':''}>${icon(i===0?screen.icon:['home','briefcase','users','calendar','chart'][i]||'file',16)}<span>${item}</span></span>`).join('')}</nav><div class="sidebar-favorites"><p>Favoritos</p><div><span class="dot"></span>Projetos da equipe</div><div><span class="dot" style="background:#9dbda9"></span>Minhas anotações</div></div><div class="sidebar-hint"><strong>${screen.id==='membros'?'Sua jornada continua':'Um espaço para boas ideias'}</strong>${screen.id==='membros'?'Uma pequena prática por dia faz diferença.':'Organize o que importa. Faça espaço para o próximo passo.'}${screen.id==='membros'?progress(42):''}</div><div class="sidebar-user">${avatar(0)}<div><strong>Marina Almeida</strong><small>Estúdio Aurora</small></div>${smallButton('more','profile','Perfil de Marina')}</div></aside>`;
  }
  function shell(screen,preview=false){return `<div class="app-shell screen-${screen.id}">${sidebar(screen)}<div class="app-body"><div class="app-header"><div class="breadcrumb">${icon(screen.icon,15)}<span>${screen.section}</span>${icon('chevron',11)}<strong>${screen.nav[0]}</strong></div><div class="header-actions"><span class="demo-label">Dados demonstrativos</span><button class="icon-button notification" data-action="notifications" aria-label="Notificações">${icon('bell',17)}</button><button class="icon-button" data-action="profile" aria-label="Perfil de Marina">${avatar(0)}</button></div></div><${preview?'div':'main'} class="main-view">${renderers[screen.id](preview)}</${preview?'div':'main'}></div></div>`;}
  function crm(){
    const all=data.deals;
    const deals=all.filter(d=>(!state.dealSearch||`${d.company} ${d.name}`.toLowerCase().includes(state.dealSearch.toLowerCase()))&&(state.dealFilter!=='Meus negócios'||d.owner==='Marina')&&(state.dealFilter!=='Acima de R$ 10 mil'||d.amount>10000));
    const stages=['Novos contatos','Em conversa','Proposta enviada','Fechados'];
    const colors=['#afa1db','#d8b77d','#8eadd3','#80b99f'];
    return heading('Seu próximo bom negócio.','Cada conversa, uma nova possibilidade.',button('Nova oportunidade','new-deal','plus','primary'))+`<div class="stats-row">${stat('Valor em pipeline',money(sum(all.filter(d=>d.stage!==3),'amount')),'+18,4%')}${stat('Oportunidades',String(all.length),'+2','neste mês','briefcase')}${stat('Negócios fechados',money(sum(all.filter(d=>d.stage===3),'amount')),'+12,8%')}${stat('Taxa de fechamento',percent(all.filter(d=>d.stage===3).length/all.length*100),'+4,2%','vs. mês anterior','target')}</div><div class="toolbar">${tabs(['Todos','Meus negócios','Acima de R$ 10 mil'],state.dealFilter,'deal-filter')}<div class="flex">${search('dealSearch',state.dealSearch,'Buscar oportunidade')}<div class="segmented">${smallButton('grid','deal-board','Visualizar kanban',`aria-pressed="${state.dealView==='board'}"`)}${smallButton('list','deal-list','Visualizar lista',`aria-pressed="${state.dealView==='list'}"`)}</div></div></div>${state.dealView==='board'?`<div class="kanban">${stages.map((s,i)=>{const rows=deals.filter(d=>d.stage===i);return `<section class="kanban-column" data-stage="${i}" aria-label="${s}"><div class="column-title"><div><span class="dot" style="color:${colors[i]}"></span>${s}<small>${rows.length}</small></div>${icon('more',13)}</div><p class="column-total">${money(sum(rows,'amount'))}</p>${rows.map(d=>`<button class="deal-card" draggable="true" data-action="deal" data-id="${d.id}"><div class="deal-company">${mark(d.letter,d.color)}${esc(d.company)}</div><h3>${esc(d.name)}</h3><strong>${money(d.amount)}</strong><div class="deal-meta">${chip(d.tag)}${avatar(d.person)}</div><div class="deal-note">${icon('message',11)}${esc(d.note)}</div><p class="deal-time">${esc(d.days)}</p></button>`).join('')}<button class="add-card" data-action="new-deal" data-stage="${i}">${icon('plus',13)}Adicionar oportunidade</button></section>`;}).join('')}</div>`:`<div class="panel table-wrap"><table class="data-table"><thead><tr><th>Oportunidade</th><th>Etapa</th><th>Responsável</th><th class="right">Valor</th><th></th></tr></thead><tbody>${deals.map(d=>`<tr><td><div class="table-name">${mark(d.letter,d.color)}<div><strong>${esc(d.company)}</strong><small>${esc(d.name)}</small></div></div></td><td>${chip(stages[d.stage],d.stage===3?'green':'')}</td><td>${esc(d.owner)}</td><td class="right">${money(d.amount)}</td><td>${smallButton('chevron','deal','Detalhes de '+esc(d.company),`data-id="${d.id}"`)}</td></tr>`).join('')}</tbody></table>${!deals.length?'<div class="empty-state">Nenhuma oportunidade com esse filtro.</div>':''}</div>`}`;
  }
  function management(){
    const rows=data.transactions.filter(t=>state.transactionFilter==='Todas'||(state.transactionFilter==='A receber'&&t.type==='receber')||(state.transactionFilter==='A pagar'&&t.type==='pagar'));
    const receivable=sum(data.transactions.filter(t=>t.status==='A receber'),'amount');
    const payable=sum(data.transactions.filter(t=>t.status==='A pagar'),'amount');
    return heading('O seu negócio, por inteiro.','Bom dia, Marina. Veja como está a operação hoje.',button('Novo lançamento','new-transaction','plus','primary'))+`<div class="stats-row">${stat('Receita do mês',money(84750),'+16,2%')}${stat('Despesas do mês',money(32900),'-4,8%')}${stat('A receber',money(receivable),String(data.transactions.filter(t=>t.status==='A receber').length),'lançamentos pendentes','wallet')}${stat('Resultado do mês',money(51850),'+24,1%')}</div><div class="two-column"><section class="panel chart-panel"><div class="panel-heading"><div><h2>Seu fluxo de caixa</h2><p>Entradas e saídas ao longo de outubro</p></div>${chip('Outubro de 2026')}</div><div class="chart-key"><span><i class="dot" style="color:var(--accent)"></i>Entradas</span><span><i class="dot" style="color:#b8a2d7"></i>Saídas</span></div>${chart([18,25,23,37,31,42,54,49,63,68,73,85],[12,17,15,21,19,25,22,28,24,29,30,33],'Entradas e saídas acumuladas de outubro')}</section><aside class="stack finance-aside"><div class="panel account-card"><div class="between"><span>Saldo disponível</span>${icon('wallet',18)}</div><strong>${money(68340)}</strong><p>Conta principal · Estúdio Aurora</p></div><div class="panel upcoming"><h3>Para ficar de olho</h3><div class="compact-row">${mark('↗','purple')}<div><strong>${money(payable)}</strong><small>Em contas a pagar</small></div>${icon('chevron',13)}</div><div class="compact-row">${mark('8','yellow')}<div><strong>8 pedidos em andamento</strong><small>Próximas entregas da equipe</small></div>${icon('chevron',13)}</div></div></aside></div><section class="panel table-panel"><div class="table-toolbar"><h2>Movimentações recentes</h2>${tabs(['Todas','A receber','A pagar'],state.transactionFilter,'transaction-filter')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Descrição</th><th>Vencimento</th><th>Situação</th><th class="right">Valor</th><th></th></tr></thead><tbody>${rows.map(t=>`<tr><td><div class="table-name">${mark(t.letter,t.color)}<div><strong>${esc(t.name)}</strong><small>${esc(t.company)}</small></div></div></td><td>${t.date}</td><td>${chip(t.status,/Pago|Recebido/.test(t.status)?'green':'')}</td><td class="right"><strong class="${t.type==='receber'?'positive':''}">${t.type==='receber'?'+':'−'} ${money(t.amount)}</strong></td><td>${smallButton('chevron','transaction','Detalhes do lançamento',`data-id="${t.id}"`)}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${rows.length} lançamentos recentes</span><span>Outubro de 2026</span></div></section>`;
  }
  function people(){
    const rows=data.people.filter(p=>(state.department==='Todos'||p.department===state.department)&&(!state.personSearch||`${p.name} ${p.role}`.toLowerCase().includes(state.personSearch.toLowerCase())));
    return heading('Um bom dia começa com as pessoas.','Sexta-feira, 16 de outubro. Seu time, um pouco mais perto.',button('Adicionar pessoa','new-person','plus','primary'))+`<div class="stats-row">${stat('Pessoas no time',String(48+data.people.length-8),'+4','neste mês','users')}${stat('Novas jornadas',String(6+data.people.length-8),'+2','em onboarding','spark')}${stat('Pessoas de férias','3','2','retornam na semana','calendar')}${stat('Clima da equipe','92%','+6%','vs. última pesquisa','heart')}</div><div class="people-layout"><div><div class="toolbar">${tabs(['Todos','Design','Tecnologia','Operações'],state.department,'department')}${search('personSearch',state.personSearch,'Buscar pessoa')}</div><div class="people-grid">${rows.map(p=>`<button class="person-card" data-action="person" data-id="${p.id}">${avatar(p.person,p.name,'lg')}<h3>${esc(p.name)}</h3><p>${esc(p.role)}</p>${chip(p.department)}<div class="person-card-foot"><span><span class="dot" style="color:${p.status==='Disponível'?'var(--green)':'#c2a16d'}"></span>${p.status}</span>${icon('chevron',12)}</div></button>`).join('')||'<div class="empty-state">Nenhuma pessoa encontrada.</div>'}</div><div class="table-footer"><span>${rows.length} pessoas em destaque</span><span>Equipe demonstrativa</span></div></div><aside class="stack people-aside"><section class="panel calendar"><div class="between"><h3>Outubro, 2026</h3>${icon('calendar',15)}</div><div class="calendar-week">${['S','T','Q','Q','S','S','D'].map((d,i)=>`<div>${d}<strong class="${i===4?'today':''}">${12+i}</strong></div>`).join('')}</div></section><section class="panel aside-events"><h3>Acontece por aqui</h3><div class="compact-row"><span class="date-tile">16</span><div><strong>Aniversário da Joana</strong><small>Um bom motivo para celebrar</small></div></div><div class="compact-row"><span class="date-tile">19</span><div><strong>Boas-vindas à Lara</strong><small>Primeiro dia no time</small></div></div><div class="compact-row"><span class="date-tile">21</span><div><strong>Conversa de equipe</strong><small>Quarta-feira, às 10h</small></div></div></section><section class="panel onboarding"><div class="flex"><span class="spark-tile">${icon('spark',17)}</span><h3>Uma boa chegada</h3></div><p>A jornada da Lara está quase pronta para começar.</p>${progress(75)}<div class="between small"><span class="muted">Onboarding</span><strong>6 de 8 etapas</strong></div></section></aside></div>`;
  }
  function ai(){const campaign=state.aiKind==='campaign';return heading('Suas ideias, com mais espaço.','Uma conversa pode ser o começo de um bom trabalho.',button('Nova conversa','new-chat','plus'))+`<div class="ai-layout"><section class="chat-column"><div class="chat-heading"><span class="spark-tile">${icon('spark',18)}</span>Numa Assistente${chip('Rascunho','purple')}</div>${state.aiPrompt?`<div class="user-message">${esc(state.aiPrompt)}</div><div class="assistant-message"><span class="spark-tile">${icon('spark',15)}</span><div class="assistant-copy"><p>${campaign?'Organizei uma campanha com um objetivo claro e espaço para testar. O primeiro rascunho está ao lado.':'Preparei um primeiro rascunho para a Casa Lina. A proposta conecta o contexto do projeto às entregas e ao investimento.'}</p><p>Separei o trabalho em três partes:</p><ul><li>${campaign?'Um objetivo e uma mensagem principal':'Contexto e direção do projeto'}</li><li>${campaign?'Conteúdos para cada momento da jornada':'Etapas e entregas com limites claros'}</li><li>${campaign?'Um plano simples de testes':'Investimento e próximos passos'}</li></ul><button class="artifact-link" data-action="edit-document">${icon('file',25)}<div><strong>${campaign?'Plano de campanha':'Proposta comercial'} — Estúdio Aurora</strong><small>Documento · Primeiro rascunho</small></div>${icon('chevron',13)}</button><p>Você pode editar o documento e ajustar o que fizer sentido para o projeto.</p></div></div>`:`<div class="assistant-message"><span class="spark-tile">${icon('spark',16)}</span><div class="assistant-copy"><p><strong>Uma boa ideia para começar?</strong></p><p>Escolha uma sugestão ou escreva o que você gostaria de construir.</p></div></div>`}<div class="prompt-suggestions"><button data-action="ai-suggestion" data-value="Crie uma proposta comercial para a Casa Lina.">Criar uma proposta</button><button data-action="ai-suggestion" data-value="Planeje uma campanha para lançar minha oficina de design.">Planejar uma campanha</button></div><form class="composer" data-form="chat"><textarea name="message" aria-label="Sua mensagem" placeholder="O que vamos criar hoje?" maxlength="1200" required>${esc(state.chatInput)}</textarea><div class="composer-footer"><span>Rascunhos demonstrativos</span><button class="button primary" type="submit" aria-label="Enviar mensagem">${icon('arrow',16)}</button></div></form><p class="ai-note">Respostas de exemplo para explorar a interface.</p></section><section class="document-panel"><div class="document-toolbar"><div class="flex">${icon('file',14)}${campaign?'Plano de campanha':'Proposta comercial'}</div><div class="flex">${button(state.aiEditing?'Concluir':'Editar','edit-document','edit')}${smallButton('copy','copy-document','Copiar documento')}</div></div><article class="document-paper" ${state.aiEditing?'contenteditable="plaintext-only" role="textbox" aria-label="Editar documento"':''}><p class="doc-kicker">ESTÚDIO AURORA</p><h2>${campaign?'Uma boa ideia merece encontrar as pessoas certas.':'Uma marca à altura do seu próximo capítulo.'}</h2><p>${campaign?'Plano de campanha · Oficina Design que resolve':'Proposta de identidade · Casa Lina'}</p><h3>01. ${campaign?'O ponto de partida':'O que vamos construir'}</h3><p>${campaign?'Apresentar a oficina a pessoas que querem criar com mais clareza e menos excesso. Uma mensagem próxima, concreta e fácil de reconhecer.':'Uma identidade que traduza o cuidado da Casa Lina em cada ponto de contato. Um sistema simples, bonito e possível de usar no dia a dia.'}</p><h3>02. ${campaign?'A conversa em três momentos':'Do primeiro encontro à entrega'}</h3><ul><li>${campaign?'Descoberta: uma pergunta que abre espaço.':'Imersão, contexto e direção criativa.'}</li><li>${campaign?'Consideração: mostrar como a oficina acontece.':'Identidade visual e seus elementos essenciais.'}</li><li>${campaign?'Convite: uma primeira experiência acessível.':'Aplicações, orientações e entrega organizada.'}</li></ul><h3>03. ${campaign?'Um primeiro teste':'Nosso próximo passo'}</h3><p>${campaign?'Testar duas mensagens durante uma semana. Observar visitas, interesse e inscrições demonstrativas antes de ampliar o alcance.':'Uma conversa para alinhar o escopo, os próximos encontros e o que mais importa para essa nova fase.'}</p><div class="doc-total"><span>${campaign?'Período de teste':'Investimento no projeto'}</span><strong>${campaign?'7 dias':money(12500)}</strong></div></article></section></div>`;}
  function members(){const c=data.courses[0];const p=c.done/c.lessons*100;return heading('Bom te ver por aqui, Marina.','Um pouco de prática hoje. Novas possibilidades amanhã.',chip('Sua jornada continua','purple'))+`<section class="panel continue-card"><div class="${courseCover(0)}"><span class="cover-label">Seu aprendizado em movimento</span></div><div class="continue-copy"><span class="eyebrow">Continue de onde parou</span><h2>Design que resolve</h2><p>Módulo 3 · Hierarquia visual na prática</p><div class="course-progress"><div class="between"><span>${c.done} de ${c.lessons} aulas concluídas</span><strong>${Math.round(p)}%</strong></div>${progress(p)}</div><button class="button primary" data-action="lesson" data-id="0">${icon('play',13)}Continuar aula</button></div></section><div class="section-line"><h2>Seu repertório está crescendo.</h2><span class="muted small">3 cursos para explorar</span></div><div class="course-grid">${data.courses.map(c=>`<article class="panel course-card"><div class="${courseCover(c.cover)}" role="img" aria-label="Arte editorial do curso ${esc(c.name)}"></div><div class="course-card-body"><span class="eyebrow">${c.category}</span><h3>${c.name}</h3><p>${c.description}</p><div class="course-progress"><div class="between"><span>${c.done?`${c.done} de ${c.lessons} aulas`:'Pronto para começar'}</span><span>${Math.round(c.done/c.lessons*100)}%</span></div>${progress(c.done/c.lessons*100)}</div></div><div class="course-card-footer"><span>${c.lessons} aulas</span><button class="text-link" data-action="lesson" data-id="${c.id}">${c.done?'Continuar':'Explorar'}${icon('arrow',13)}</button></div></article>`).join('')}</div><div class="learning-bottom"><div class="panel learning-note">${icon('award',23)}<div><strong>Aprender também é reconhecer o caminho.</strong><small>Seus certificados ficam disponíveis ao concluir um curso.</small></div></div><div class="panel learning-note">${icon('calendar',22)}<div><strong>Encontro de prática criativa</strong><small>Quarta-feira, 21 de outubro · 19h</small></div></div></div>`;}
  function community(){const posts=data.posts.filter(p=>state.feedFilter==='Para você'||(state.feedFilter==='Salvos'?p.saved:p.category===state.feedFilter));return `<section class="community-banner"><div><h1>Um lugar para quem<br>gosta de fazer.</h1><p>Compartilhe o processo. Encontre novas possibilidades.</p></div><div><div class="avatar-group">${avatar(0)}${avatar(2)}${avatar(4)}<small>+128 pessoas criando juntas</small></div></div></section><div class="community-layout"><div><div class="community-tabs">${tabs(['Para você','Discussões','Projetos','Salvos'],state.feedFilter,'feed-filter')}</div><button class="feed-composer" data-action="new-post">${avatar(0)}O que você está construindo, Marina?<span class="icon-button">${icon('plus',14)}</span></button>${posts.map(p=>`<article class="panel post-card"><div class="post-person">${avatar(p.person,p.name,'md')}<div><strong>${esc(p.name)}</strong><small>${p.time} · ${p.category}</small></div>${p.pinned?chip(`${icon('pin',10)}Fixado`):''}</div><h2>${esc(p.title)}</h2><p>${esc(p.body)}</p>${p.cover!==undefined?`<div class="${courseCover(p.cover)}" role="img" aria-label="Estudo de formas e materiais do projeto"></div>`:''}<div class="post-actions"><button data-action="like" data-id="${p.id}" class="${p.liked?'active':''}" aria-pressed="${p.liked}">${icon('heart',15)}${p.likes}</button><button data-action="comments" data-id="${p.id}">${icon('message',15)}${p.comments} comentários</button><button data-action="save-post" data-id="${p.id}" class="${p.saved?'active':''}" aria-label="${p.saved?'Remover dos salvos':'Salvar publicação'}" aria-pressed="${p.saved}">${icon('bookmark',15)}</button></div>${state.comments===p.id?`<div class="post-comments">${p.comment?`<strong>Marina</strong><p>${esc(p.comment)}</p>`:'Uma boa conversa começa com uma pergunta.'}<form data-form="comment" data-id="${p.id}"><input name="comment" aria-label="Seu comentário" placeholder="Participe da conversa" maxlength="280" required><button class="button" type="submit">Enviar</button></form></div>`:''}</article>`).join('')||'<div class="panel empty-state">As publicações salvas aparecerão aqui.</div>'}</div><aside class="stack community-aside"><section class="panel event-card"><div class="event-visual"><strong>21</strong><div>outubro<br>quarta-feira</div>${icon('spark',31)}</div>${chip('Próximo encontro','purple')}<h3>Criação é conversa.</h3><p>Um encontro aberto para compartilhar processos, ideias e boas perguntas.</p><div class="avatar-group" style="margin-bottom:18px">${avatar(2)}${avatar(1)}${avatar(4)}<small>24 participantes</small></div><button class="button ${state.eventJoined?'tinted':'primary'} wide" data-action="join-event">${icon(state.eventJoined?'check':'calendar',14)}${state.eventJoined?'Participação confirmada':'Quero participar'}</button></section><section class="panel members-panel"><h3>Gente para conhecer</h3>${[data.people[1],data.people[2],data.people[4]].map(p=>`<div class="compact-row">${avatar(p.person,p.name)}<div><strong>${p.name}</strong><small>${p.role}</small></div></div>`).join('')}</section></aside></div>`;}
  const quizArt=()=>`<svg class="quiz-art" viewBox="0 0 240 240" fill="none" aria-hidden="true"><circle cx="120" cy="120" r="90" fill="var(--accent-soft)"/><path d="M120 29C170 29 170 75 120 120C75 75 75 29 120 29Z" fill="#ab9bdf"/><path d="M211 120C211 170 165 170 120 120C165 75 211 75 211 120Z" fill="#d6c9a5"/><path d="M120 211C70 211 70 165 120 120C165 165 165 211 120 211Z" fill="#a0c5b2"/><path d="M29 120C29 70 75 70 120 120C75 165 29 165 29 120Z" fill="#b8cbe6"/><circle cx="120" cy="120" r="19" fill="var(--surface)"/><path d="M116 120l3 3 6-7" stroke="var(--accent)" stroke-width="2" stroke-linecap="round"/></svg>`;
  function quiz(){
    if(state.quizDone){const counts=[0,0,0,0];state.quizAnswers.forEach(a=>counts[a]++);const i=counts.indexOf(Math.max(...counts));const profiles=['Estrategista','Conector','Criador','Explorador'];const descriptions=['Você encontra clareza no meio de muitas possibilidades. Conecta as peças, define prioridades e ajuda uma boa ideia a encontrar seu caminho.','Você aproxima pessoas e faz boas perguntas. O seu jeito de ouvir e compartilhar transforma ideias individuais em construções coletivas.','Você aprende colocando a mão na massa. Uma versão pequena, um teste concreto e um próximo passo são os seus melhores parceiros.','Você enxerga possibilidades onde outras pessoas veem um caminho pronto. Curiosidade e repertório ajudam você a construir novas perspectivas.'];return heading('Uma nova perspectiva sobre você.','Um ponto de partida para experimentar o seu jeito de criar.')+`<section class="panel quiz-result">${quizArt()}${chip('Seu perfil criativo','purple')}<h2>${profiles[i]}, com espaço para descobrir.</h2><p>${descriptions[i]}</p><div class="result-traits"><div><strong>${counts[i]}/5</strong>respostas nesse perfil</div><div><strong>5</strong>escolhas que contam</div><div><strong>∞</strong>jeitos de experimentar</div></div><p class="small">Este é um exercício criativo demonstrativo, sem avaliação psicológica.</p><button class="button primary" data-action="quiz-restart">Fazer de novo${icon('arrow',15)}</button></section>`;}
    const q=data.quiz[state.quizStep];return heading('Qual é o seu jeito de criar?','Uma pequena descoberta. Novas possibilidades para colocar em prática.')+`<div class="quiz-layout"><section class="panel quiz-main"><div class="quiz-progress"><span>Pergunta ${state.quizStep+1} de ${data.quiz.length}</span><span>Cerca de 2 minutos</span></div>${progress((state.quizStep+1)/data.quiz.length*100)}<h2>${q.question}</h2><p>${q.hint}</p><div class="quiz-options" role="radiogroup" aria-label="Escolha sua resposta">${q.options.map((o,i)=>`<label class="quiz-option"><input type="radio" name="quizAnswer" value="${i}" ${state.quizAnswers[state.quizStep]===i?'checked':''}><span class="option-letter">${'ABCD'[i]}</span><span>${o}</span>${state.quizAnswers[state.quizStep]===i?`<span class="spacer"></span>${icon('check',15)}`:''}</label>`).join('')}</div><div class="quiz-navigation"><button class="button ghost" data-action="quiz-back" ${state.quizStep===0?'disabled':''}>${icon('back',14)}Voltar</button><button class="button primary" data-action="quiz-next" ${state.quizAnswers[state.quizStep]===undefined?'disabled':''}>${state.quizStep===4?'Ver meu perfil':'Continuar'}${icon('arrow',15)}</button></div></section><aside class="quiz-aside">${quizArt()}<h3>Não existe resposta certa.<br>Existe o seu jeito.</h3><p>Responda pensando em como você se sente hoje. Uma escolha por vez, no seu ritmo.</p>${chip(`${icon('check',12)}Seu resultado aparece ao final`)}</aside></div>`;
  }
  function estimate(){const c=state.calc;const hours=Math.ceil(({Website:24,Aplicativo:48,Marca:16}[c.type]+c.pages*3+(c.content?12:0)+(c.prototype?8:0)+(c.support?6:0))*({Essencial:.85,Completo:1,Avançado:1.35}[c.complexity]));const total=hours*c.rate*({'Flexível':1,'30 dias':1.1,'15 dias':1.25}[c.deadline]);return {hours,total:Math.round(total),design:Math.round(total*.35),development:Math.round(total*.5),review:Math.round(total)-Math.round(total*.35)-Math.round(total*.5)};}
  function calculator(){const c=state.calc,e=estimate();return heading('Boas ideias, números claros.','Monte uma estimativa para seu próximo projeto.',chip('Simulação de orçamento','purple'))+`<div class="calculator-layout"><section class="panel calculator-form"><div class="field-group"><label>O que vamos criar?</label><div class="segmented">${['Website','Aplicativo','Marca'].map(t=>`<button class="tab ${c.type===t?'active':''}" data-action="calc-type" data-value="${t}" aria-pressed="${c.type===t}">${icon(t==='Website'?'grid':t==='Aplicativo'?'shapes':'spark',14)}${t}</button>`).join('')}</div></div><div class="field-group"><div class="between"><label for="calc-pages">${c.type==='Marca'?'Peças e aplicações':'Páginas ou telas'}</label><strong>${c.pages} ${c.type==='Marca'?'peças':'telas'}</strong></div><input id="calc-pages" type="range" name="calcPages" min="3" max="24" value="${c.pages}"><div class="range-labels"><span>3 ${c.type==='Marca'?'peças':'telas'}</span><span>24 ${c.type==='Marca'?'peças':'telas'}</span></div></div><div class="field-group"><label>Quanto detalhe faz sentido?</label><div class="segmented">${['Essencial','Completo','Avançado'].map(t=>`<button class="tab ${c.complexity===t?'active':''}" data-action="calc-complexity" data-value="${t}" aria-pressed="${c.complexity===t}">${t}</button>`).join('')}</div></div><div class="field-group"><label for="calc-deadline">Prazo para o projeto</label><select id="calc-deadline" name="calcDeadline">${['Flexível','30 dias','15 dias'].map(t=>`<option ${c.deadline===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field-group"><div class="between"><label for="calc-rate">Valor de referência por hora</label><strong>${money(c.rate)}</strong></div><input id="calc-rate" type="range" name="calcRate" min="80" max="300" step="10" value="${c.rate}"><div class="range-labels"><span>${money(80)}</span><span>${money(300)}</span></div></div><div class="add-ons"><p>Um pouco mais de cuidado</p>${[['content','Conteúdo e textos',12],['prototype','Protótipo navegável',8],['support','Acompanhamento da entrega',6]].map(([k,l,h])=>`<label class="add-on"><input type="checkbox" name="calcAddon" value="${k}" ${c[k]?'checked':''}>${l}<small>+${h} horas de base</small></label>`).join('')}</div></section><aside class="stack estimate-side"><section class="panel estimate-panel"><p>Seu projeto pode começar com</p><strong class="estimate-total">${money(e.total)}</strong><small>${c.type} · ${c.complexity.toLowerCase()} · ${c.pages} ${c.type==='Marca'?'peças':'telas'}</small><div class="divider"></div><div class="estimate-row"><span>Design e direção</span><strong>${money(e.design)}</strong></div><div class="estimate-row"><span>Produção e desenvolvimento</span><strong>${money(e.development)}</strong></div><div class="estimate-row"><span>Revisão e entrega</span><strong>${money(e.review)}</strong></div><div class="divider"></div><div class="estimate-row"><span>Dedicação estimada</span><strong>${e.hours} horas</strong></div><button class="button" data-action="save-scenario">${icon('plus',14)}Comparar cenário</button><div class="estimate-note">Estimativa ilustrativa. Ajuste ao seu projeto.</div></section><section class="panel estimate-bottom"><h3>Cada etapa tem seu espaço.</h3><div class="stacked-bar"><span style="width:35%;background:#9987d6"></span><span style="width:50%;background:#9bbda9"></span><span style="width:15%;background:#d9b89a"></span></div><div class="estimate-key"><span><i class="dot" style="color:#9987d6"></i>Design</span><span><i class="dot" style="color:#9bbda9"></i>Produção</span><span><i class="dot" style="color:#d9b89a"></i>Revisão</span></div></section></aside></div>${state.scenarios.length?`<section class="panel scenario-panel"><div class="between"><h3>Encontre um caminho que faça sentido.</h3><button class="text-link" data-action="clear-scenarios">Limpar</button></div><div class="scenario-grid">${state.scenarios.map((s,i)=>`<div class="scenario"><span>Cenário ${'AB'[i]}</span><strong>${money(s.total)}</strong><p>${s.type} · ${s.pages} ${s.type==='Marca'?'peças':'telas'} · ${s.hours} horas</p></div>`).join('')}</div></section>`:''}`;}
  function analytics(){
    const scale=Number(state.period)/30;
    const rows=data.campaigns.filter(c=>state.channel==='Todos os canais'||c.channel===state.channel).map(c=>({...c,spend:Math.round(c.spend*scale),revenue:Math.round(c.revenue*scale),conversions:Math.round(c.conversions*scale),visits:Math.round(c.visits*scale)}));
    const revenue=sum(rows,'revenue'),spend=sum(rows,'spend'),visits=sum(rows,'visits'),conversions=sum(rows,'conversions'),paidRevenue=sum(rows.filter(r=>r.spend>0),'revenue');
    const base=[3,5,4,7,5,8,7,10,8,12,11,14];const vals=base.map(n=>n/base.reduce((a,b)=>a+b,0)*revenue/1000);
    return heading('Cada resultado tem um caminho.','Veja o que aproxima as pessoas da sua próxima conversão.',periodSelect())+`<div class="stats-row">${stat('Receita atribuída',money(revenue),'+21,6%')}${stat('Conversões',number(conversions),'+16,2%','no período','target')}${stat('Taxa de conversão',percent(conversions/Math.max(1,visits)*100),'+0,8%','vs. período anterior','chart')}${stat('ROAS de mídia paga',spend?number(Math.round(paidRevenue/spend*10)/10)+'×':'—','+12,4%')}</div><div class="two-column"><section class="panel analytics-chart"><div class="panel-heading"><div><h2>A evolução dos seus resultados</h2><p>Receita atribuída no período selecionado</p></div>${chip(`${icon('trend',11)}Tendência positiva`,'green')}</div><div class="chart-key"><span><i class="dot" style="color:var(--accent)"></i>Receita</span><span class="muted">${state.channel}</span></div>${chart(vals,null,'Receita atribuída no período')}</section><section class="panel funnel"><h3>Do primeiro clique à compra</h3>${[['Visitas',visits],['Páginas de produto',Math.round(visits*.41)],['Checkout',Math.round(visits*.081)],['Conversões',conversions]].map(([name,value])=>`<div class="funnel-step"><div class="between"><span>${name}</span><strong>${number(value)}</strong></div>${progress(value/Math.max(1,visits)*100)}<small>${percent(value/Math.max(1,visits)*100)}</small></div>`).join('')}</section></div><section class="panel table-panel"><div class="table-toolbar"><div><h2>Campanhas e canais</h2><p class="muted small" style="margin-top:4px">Encontre o que está fazendo a diferença.</p></div><select name="channel" class="period-select" aria-label="Filtrar canal">${['Todos os canais',...data.campaigns.map(c=>c.channel)].map(c=>`<option ${state.channel===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Campanha</th><th>Canal</th><th class="right">Investimento</th><th class="right">Receita</th><th class="right">Conversões</th><th class="right">ROAS</th><th></th></tr></thead><tbody>${rows.map((c,i)=>`<tr><td><div class="table-name">${mark(c.letter,c.color)}<strong>${c.name}</strong></div></td><td><span class="muted">${c.channel}</span></td><td class="right">${money(c.spend)}</td><td class="right"><strong>${money(c.revenue)}</strong></td><td class="right">${number(c.conversions)}</td><td class="right"><span class="chip ${c.spend?'green':''}">${c.spend?number(Math.round(c.revenue/c.spend*10)/10)+'×':'—'}</span></td><td>${smallButton('chevron','campaign','Detalhes da campanha',`data-id="${data.campaigns.findIndex(r=>r.name===c.name)}"`)}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${rows.length} campanhas demonstrativas</span><span>ROAS: receita de mídia paga ÷ investimento</span></div></section>`;
  }
  const renderers={crm,gestao:management,pessoas:people,ia:ai,membros:members,comunidade:community,quiz,calculadora:calculator,conversoes:analytics};
  function renderGallery(){return reviewBar()+`<main class="gallery"><div class="gallery-intro"><div><div class="gallery-kicker">${brand()}Numa · estudos de aplicativos</div><h1>Uma família. Nove jeitos<br>de colocar ideias em prática.</h1><p>Explore as telas, alterne entre os temas e experimente as interações.<br>Uma direção visual comum, com espaço para o que torna cada produto único.</p></div><div class="gallery-note">9 telas demonstrativas<br>Temas claro e escuro<br>Conteúdo e dados fictícios</div></div><div class="gallery-grid">${data.screens.map(s=>`<article class="gallery-card" data-action="open" data-screen="${s.id}"><div class="screen-thumb" inert aria-hidden="true"><div class="preview-frame">${shell(s,true)}</div></div><div class="gallery-card-info"><div><h2>${s.name}</h2><p>${s.description}</p></div><button class="icon-button" data-action="open" data-screen="${s.id}" aria-label="Abrir ${s.name}">${icon('arrow',17)}</button></div></article>`).join('')}</div><footer class="gallery-footer"><span>Spike visual para validação · SquadOS Studio</span><span>Marca fictícia, dados ilustrativos e interações locais.</span></footer></main>`;}
  const currentScreen=()=>data.screens.find(s=>s.id===location.hash.slice(1));
  function render(preserveFocus=false){
    const previous=document.activeElement,name=previous?.name,start=previous?.selectionStart;
    galleryObserver?.disconnect();
    document.documentElement.dataset.theme=state.theme;
    const screen=currentScreen();
    document.title=screen?`Numa — ${screen.name}`:'Numa — estudos de aplicativos';
    app.innerHTML=screen?reviewBar(screen)+shell(screen):renderGallery();
    if(screen?.id==='ia'&&state.aiDraftHTML!==null)app.querySelector('.document-paper').innerHTML=state.aiDraftHTML;
    if(!screen){galleryObserver=new ResizeObserver(entries=>entries.forEach(e=>{e.target.querySelector('.preview-frame').style.setProperty('--preview-scale',e.contentRect.width/1280);e.target.style.height=(e.contentRect.width/1280*820)+'px';}));document.querySelectorAll('.screen-thumb').forEach(e=>galleryObserver.observe(e));}
    if(preserveFocus&&name){const target=app.querySelector(`[name="${name}"]`);if(target){target.focus({preventScroll:true});if(['text','search'].includes(target.type)&&typeof start==='number')target.setSelectionRange(start,start);}}
  }
  function go(id){if(dialog.open)dialog.close();if(location.hash==='#'+id)render();else location.hash=id;}
  function toast(text){clearTimeout(toastTimer);const t=document.querySelector('#toast');t.textContent=text;t.classList.add('visible');toastTimer=setTimeout(()=>t.classList.remove('visible'),2800);}
  function openDialog(title,content,drawer=false){dialogOpener=document.activeElement;dialog.className=drawer?'drawer':'';document.querySelector('#dialog-content').innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${title}</h2>${smallButton('close','close-dialog','Fechar')}</div>${content}`;dialog.showModal();}
  function closeDialog(){dialog.close();}
  function sendChat(prompt){state.aiDraftHTML=null;state.chatInput='';state.aiPrompt=prompt.trim();state.aiKind=/campanha|oficina|lançar/i.test(prompt)?'campaign':'proposal';state.aiEditing=false;render();}
  function openLesson(id){const c=data.courses[id];state.course=id;openDialog(c.name,`<div class="lesson-art ${courseCover(c.cover)}"></div><div class="lesson-text"><span class="eyebrow">Aula demonstrativa · ${c.category}</span><h3>Uma decisão pequena, uma ideia mais clara.</h3><p>Antes de procurar uma solução, observe o que você quer tornar mais simples. Um bom projeto começa com uma pergunta que vale a pena fazer.</p><ul><li>Escolha uma situação real do seu dia.</li><li>Escreva o que poderia funcionar melhor.</li><li>Imagine uma versão pequena para experimentar.</li></ul><p>Essa é uma prévia textual para explorar a experiência de aprendizado.</p><button class="button primary" data-action="complete-lesson" data-id="${id}">${icon('check',15)}Marcar aula como concluída</button></div>`);}
  // Interações locais do spike; a navegação secundária é somente composição visual.
  document.addEventListener('click',event=>{
    const el=event.target.closest('[data-action]');if(!el||el.closest('[inert]'))return;
    const action=el.dataset.action,id=Number(el.dataset.id),value=el.dataset.value;
    if(action==='open'){go(el.dataset.screen);return;}
    if(action==='gallery'){go('galeria');return;}
    if(action==='theme'){state.theme=state.theme==='light'?'dark':'light';render();return;}
    if(action==='previous'||action==='next'){const i=data.screens.indexOf(currentScreen());go(data.screens[(i+(action==='next'?1:8))%9].id);return;}
    if(action==='close-dialog'){closeDialog();return;}
    if(action==='profile'){openDialog('Bom te ver, Marina.',`<div class="detail-profile">${avatar(0,'Marina Almeida','xl')}<h3>Marina Almeida</h3><p>Designer · Estúdio Aurora</p></div><div class="note-box">Este perfil faz parte do estudo visual da Numa. Todos os dados desta experiência são fictícios.</div>`);return;}
    if(action==='notifications'){openDialog('Novidades por aqui',`<div class="compact-row">${mark('✓','green')}<div><strong>Uma nova etapa concluída</strong><small>O projeto da Casa Una está pronto para começar.</small></div></div><div class="compact-row">${mark('21','purple')}<div><strong>Encontro de prática criativa</strong><small>Quarta-feira, 21 de outubro, às 19h.</small></div></div><div class="compact-row">${mark('a.','peach')}<div><strong>Bem-vinda ao seu espaço</strong><small>Explore as possibilidades da Numa.</small></div></div>`);return;}
    if(action==='deal-filter'){state.dealFilter=value;render();return;}
    if(action==='deal-board'||action==='deal-list'){state.dealView=action==='deal-board'?'board':'list';render();return;}
    if(action==='new-deal'){state.newStage=Number(el.dataset.stage)||0;openDialog('Uma nova possibilidade.',`<form class="modal-form" data-form="deal"><label>Empresa<input name="company" required minlength="2" maxlength="60" placeholder="Nome da empresa"></label><label>Oportunidade<input name="opportunity" required minlength="2" maxlength="90" placeholder="O que vamos construir?"></label><label>Valor estimado em reais<input type="number" name="amount" required min="1" max="1000000" step="1" placeholder="12000"></label><button class="button primary" type="submit">Adicionar oportunidade</button><p class="modal-note">Oportunidade criada somente nesta demonstração.</p></form>`);return;}
    if(action==='deal'){const d=data.deals.find(d=>d.id===id);openDialog(esc(d.company),`<div class="flex">${mark(d.letter,d.color)}<div><span class="eyebrow">${esc(d.tag)}</span><h3>${esc(d.name)}</h3></div></div><div class="detail-list"><div><span>Valor da oportunidade</span><strong>${money(d.amount)}</strong></div><div><span>Responsável</span><span>${esc(d.owner)}</span></div><div><span>Próximo passo</span><span>${esc(d.note)}</span></div></div><form class="modal-form" data-form="move-deal" data-id="${id}"><label>Etapa do negócio<select name="stage">${['Novos contatos','Em conversa','Proposta enviada','Fechados'].map((s,i)=>`<option value="${i}" ${d.stage===i?'selected':''}>${s}</option>`).join('')}</select></label><button class="button primary" type="submit">Salvar etapa</button></form>`,true);return;}
    if(action==='transaction-filter'){state.transactionFilter=value;render();return;}
    if(action==='new-transaction'){openDialog('Novo lançamento',`<form class="modal-form" data-form="transaction"><label>Descrição<input name="description" required minlength="2" maxlength="80" placeholder="Nome do lançamento"></label><label>Tipo<select name="type"><option value="receber">A receber</option><option value="pagar">A pagar</option></select></label><label>Valor em reais<input name="amount" type="number" min="1" max="1000000" step="1" required></label><button class="button primary" type="submit">Adicionar lançamento</button></form>`);return;}
    if(action==='transaction'){const t=data.transactions.find(t=>t.id===id);openDialog(esc(t.name),`<div class="detail-list"><div><span>Empresa</span><strong>${esc(t.company)}</strong></div><div><span>Valor</span><strong>${money(t.amount)}</strong></div><div><span>Vencimento</span><span>${t.date}</span></div><div><span>Situação</span>${chip(t.status)}</div></div>${/^A /.test(t.status)?`<button class="button primary wide" data-action="settle-transaction" data-id="${id}">${icon('check',14)}Marcar como ${t.type==='receber'?'recebido':'pago'}</button>`:'<p class="note-box">Este lançamento demonstrativo já foi concluído.</p>'}`);return;}
    if(action==='settle-transaction'){const t=data.transactions.find(t=>t.id===id);t.status=t.type==='receber'?'Recebido':'Pago';closeDialog();render();toast('Lançamento atualizado na demonstração.');return;}
    if(action==='department'){state.department=value;render();return;}
    if(action==='new-person'){openDialog('Um novo começo no time.',`<form class="modal-form" data-form="person"><label>Nome<input name="personName" required minlength="2" maxlength="60"></label><label>Cargo<input name="role" required minlength="2" maxlength="60"></label><label>Departamento<select name="department"><option>Design</option><option>Tecnologia</option><option>Operações</option><option>Marketing</option></select></label><button class="button primary" type="submit">Adicionar pessoa</button></form>`);return;}
    if(action==='person'){const p=data.people.find(p=>p.id===id);openDialog(esc(p.name),`<div class="detail-profile">${avatar(p.person,p.name,'xl')}<h3>${esc(p.name)}</h3><p>${esc(p.role)}</p></div><div class="detail-list"><div><span>Departamento</span><strong>${esc(p.department)}</strong></div><div><span>Localização</span><span>${esc(p.city)}</span></div><div><span>Jornada</span><span>Tempo integral</span></div><div><span>Situação</span>${chip(p.status,'green')}</div></div><div class="note-box">Um perfil demonstrativo para imaginar como o seu time pode se conectar.</div>`,true);return;}
    if(action==='new-chat'){state.aiPrompt='';state.aiEditing=false;state.aiDraftHTML=null;state.chatInput='';render();return;}
    if(action==='ai-suggestion'){sendChat(value);return;}
    if(action==='edit-document'){const paper=app.querySelector('.document-paper');if(state.aiEditing){state.aiEditing=false;paper.contentEditable='false';const edit=app.querySelector('.document-toolbar [data-action="edit-document"]');if(edit){edit.innerHTML=icon('edit',14)+'Editar';edit.setAttribute('aria-pressed','false');}toast('Rascunho editado nesta página.');}else{state.aiEditing=true;paper.contentEditable='plaintext-only';paper.setAttribute('role','textbox');paper.setAttribute('aria-label','Editar documento');paper.focus();const edit=app.querySelector('[data-action="edit-document"].button');if(edit)edit.innerHTML=icon('check',14)+'Concluir';}return;}
    if(action==='copy-document'){const text=app.querySelector('.document-paper').innerText;navigator.clipboard?.writeText(text).then(()=>toast('Documento copiado.')).catch(()=>toast('Selecione o texto do documento para copiar.'));if(!navigator.clipboard)toast('Selecione o texto do documento para copiar.');return;}
    if(action==='lesson'){openLesson(id);return;}
    if(action==='complete-lesson'){const c=data.courses[id];c.done=Math.min(c.lessons,c.done+1);closeDialog();render();toast('Mais um passo no seu aprendizado.');return;}
    if(action==='feed-filter'){state.feedFilter=value;render();return;}
    if(action==='new-post'){openDialog('Compartilhe o processo.',`<form class="modal-form" data-form="post"><label>Título<input name="title" required minlength="3" maxlength="100" placeholder="Uma ideia para abrir a conversa"></label><label>Sua publicação<textarea name="body" required minlength="3" maxlength="1200" placeholder="O que você está construindo?"></textarea></label><label>Espaço<select name="category"><option>Discussões</option><option>Projetos</option></select></label><button class="button primary" type="submit">Publicar nesta demonstração</button></form>`);return;}
    if(action==='like'){const p=data.posts.find(p=>p.id===id);p.liked=!p.liked;p.likes+=p.liked?1:-1;render();return;}
    if(action==='save-post'){const p=data.posts.find(p=>p.id===id);p.saved=!p.saved;render();toast(p.saved?'Publicação salva.':'Publicação removida dos salvos.');return;}
    if(action==='comments'){state.comments=state.comments===id?null:id;render();return;}
    if(action==='join-event'){state.eventJoined=!state.eventJoined;render();toast(state.eventJoined?'Participação confirmada nesta demonstração.':'Participação removida.');return;}
    if(action==='quiz-next'){if(state.quizAnswers[state.quizStep]===undefined)return;if(state.quizStep===4)state.quizDone=true;else state.quizStep++;render();return;}
    if(action==='quiz-back'){state.quizStep=Math.max(0,state.quizStep-1);render();return;}
    if(action==='quiz-restart'){state.quizStep=0;state.quizAnswers=[];state.quizDone=false;render();return;}
    if(action==='calc-type'){state.calc.type=value;render();return;}
    if(action==='calc-complexity'){state.calc.complexity=value;render();return;}
    if(action==='save-scenario'){const e=estimate();if(state.scenarios.length===2)state.scenarios.shift();state.scenarios.push({...state.calc,...e});render();toast('Cenário adicionado à comparação.');return;}
    if(action==='clear-scenarios'){state.scenarios=[];render();return;}
    if(action==='campaign'){const c=data.campaigns[id];const scale=Number(state.period)/30;openDialog(esc(c.name),`<div class="flex">${mark(c.letter,c.color)}<div><h3>${c.channel}</h3><span class="muted small">Últimos ${state.period} dias</span></div></div><div class="detail-list"><div><span>Investimento</span><strong>${money(c.spend*scale)}</strong></div><div><span>Receita atribuída</span><strong>${money(c.revenue*scale)}</strong></div><div><span>Conversões</span><strong>${number(Math.round(c.conversions*scale))}</strong></div><div><span>Visitas</span><strong>${number(Math.round(c.visits*scale))}</strong></div></div><div class="note-box"><strong>Origem demonstrativa</strong><br>utm_source=${esc(c.channel.toLowerCase().replaceAll(' ','_'))}<br>utm_campaign=primeiro_passo<br>Modelo ilustrativo: último clique</div>`,true);}
  });
  document.addEventListener('submit',event=>{
    const form=event.target;if(!form.dataset.form)return;event.preventDefault();if(!form.reportValidity())return;const values=new FormData(form),kind=form.dataset.form;
    if(kind==='deal'){data.deals.unshift({id:Date.now(),company:values.get('company'),name:values.get('opportunity'),amount:Number(values.get('amount')),stage:state.newStage||0,owner:'Marina',tag:'Novo projeto',color:'purple',letter:initials(values.get('company')).toLowerCase(),person:0,note:'Próximo passo a definir',days:'Agora'});state.dealFilter='Todos';state.dealSearch='';closeDialog();render();toast('Nova oportunidade adicionada.');}
    if(kind==='move-deal'){data.deals.find(d=>d.id===Number(form.dataset.id)).stage=Number(values.get('stage'));closeDialog();render();toast('Etapa atualizada.');}
    if(kind==='transaction'){const type=values.get('type');data.transactions.unshift({id:Date.now(),name:values.get('description'),company:'Estúdio Aurora',type,amount:Number(values.get('amount')),date:'16 out',status:type==='receber'?'A receber':'A pagar',color:'purple',letter:'a.'});state.transactionFilter='Todas';closeDialog();render();toast('Lançamento adicionado.');}
    if(kind==='person'){data.people.unshift({id:Date.now(),name:values.get('personName'),role:values.get('role'),department:values.get('department'),person:8,status:'Onboarding',city:'São Paulo'});state.department='Todos';state.personSearch='';closeDialog();render();toast('Pessoa adicionada à demonstração.');}
    if(kind==='chat')sendChat(String(values.get('message')));
    if(kind==='post'){data.posts.unshift({id:Date.now(),name:'Marina Almeida',person:0,time:'Agora',category:values.get('category'),title:values.get('title'),body:values.get('body'),likes:0,comments:0,liked:false,saved:false});state.feedFilter='Para você';closeDialog();render();toast('Publicação adicionada somente nesta página.');}
    if(kind==='comment'){const p=data.posts.find(p=>p.id===Number(form.dataset.id));p.comment=values.get('comment');p.comments++;render();}
  });
  document.addEventListener('input',event=>{const t=event.target;if(t.closest('[inert]'))return;if(t.closest('.document-paper')){state.aiDraftHTML=t.closest('.document-paper').innerHTML;return;}if(t.name==='message')state.chatInput=t.value;if(t.name==='dealSearch'||t.name==='personSearch'){state[t.name]=t.value;render(true);}if(t.name==='calcPages'){state.calc.pages=Number(t.value);render(true);}if(t.name==='calcRate'){state.calc.rate=Number(t.value);render(true);}});
  document.addEventListener('change',event=>{const t=event.target;if(t.closest('[inert]'))return;if(t.name==='screen-switch')go(t.value);if(t.name==='quizAnswer'){state.quizAnswers[state.quizStep]=Number(t.value);const pos=state.quizAnswers[state.quizStep];render();app.querySelector(`input[name="quizAnswer"][value="${pos}"]`)?.focus({preventScroll:true});}if(t.name==='calcDeadline'){state.calc.deadline=t.value;render(true);}if(t.name==='calcAddon'){state.calc[t.value]=t.checked;render();}if(t.name==='period'){state.period=t.value;render();}if(t.name==='channel'){state.channel=t.value;render();}});
  document.addEventListener('dragstart',event=>{const card=event.target.closest('.deal-card');if(card&&!card.closest('[inert]')){event.dataTransfer.setData('text/plain',card.dataset.id);event.dataTransfer.effectAllowed='move';}});
  document.addEventListener('dragover',event=>{const column=event.target.closest('.kanban-column');if(column&&!column.closest('[inert]')){event.preventDefault();column.classList.add('drag-over');}});
  document.addEventListener('dragleave',event=>event.target.closest('.kanban-column')?.classList.remove('drag-over'));
  document.addEventListener('drop',event=>{const column=event.target.closest('.kanban-column');if(!column||column.closest('[inert]'))return;event.preventDefault();const d=data.deals.find(d=>d.id===Number(event.dataTransfer.getData('text/plain')));if(d){d.stage=Number(column.dataset.stage);render();toast('Oportunidade movida.');}});
  dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
  dialog.addEventListener('close',()=>{if(dialogOpener?.isConnected)dialogOpener.focus({preventScroll:true});else app.querySelector('.review-center select,.review-home')?.focus({preventScroll:true});});
  window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
  render();
})();
